  // ========== CICLO DE REPRODUCCIÓN ==========
  cicloReproduccion(): void {
    const modos: Array<'ninguno' | 'capitulo' | 'manual'> = ['ninguno', 'capitulo', 'manual'];
    const currentIndex = modos.indexOf(this.modoRepeticion);
    this.modoRepeticion = modos[(currentIndex + 1) % modos.length];

    this.notificationService.addNotification({
      userId: 'Sistema',
      title: 'Modo repetición cambiado',
      message: `Modo repetición: ${this.getModoRepeticionTexto()}`,
      metadata: { avatar: this.getModoRepeticionIcon() },
      module: 'audiovisual',
      type: 'info'
    });
  }

  getModoRepeticionIcon(): string {
    switch (this.modoRepeticion) {
      case 'capitulo': return '🔂';
      case 'manual': return '🔁';
      default: return '➰';
    }
  }

  getModoRepeticionTexto(): string {
    switch (this.modoRepeticion) {
      case 'capitulo': return 'Repetir capítulo';
      case 'manual': return 'Repetir manual';
      default: return 'Sin repetición';
    }
  }

